import { test } from 'node:test';
import assert from 'node:assert/strict';
import { addBook, markRead, listBooks } from '../src/reading-list.js';

test('addBook appends a book with an incrementing id, unread', () => {
  let books = addBook([], { title: 'Dune', author: 'Frank Herbert' });
  books = addBook(books, { title: 'Emma' });
  assert.deepEqual(books, [
    { id: 1, title: 'Dune', author: 'Frank Herbert', read: false },
    { id: 2, title: 'Emma', author: null, read: false },
  ]);
});

test('addBook ids stay unique after gaps', () => {
  const books = addBook([{ id: 5, title: 'X', author: null, read: false }], { title: 'Y' });
  assert.equal(books[1].id, 6);
});

test('addBook rejects an empty title', () => {
  assert.throws(() => addBook([], { title: '   ' }), /title is required/i);
});

test('addBook does not mutate its input', () => {
  const books = [];
  addBook(books, { title: 'Dune' });
  assert.equal(books.length, 0);
});

test('markRead marks the matching book as read', () => {
  const books = addBook(addBook([], { title: 'A' }), { title: 'B' });
  const updated = markRead(books, 2);
  assert.equal(updated[0].read, false);
  assert.equal(updated[1].read, true);
  assert.equal(books[1].read, false);
});

test('markRead throws for an unknown id', () => {
  assert.throws(() => markRead([], 3), /no book with id 3/i);
});

test('listBooks filters by status', () => {
  const books = markRead(addBook(addBook([], { title: 'A' }), { title: 'B' }), 1);
  assert.deepEqual(listBooks(books).map((b) => b.title), ['A', 'B']);
  assert.deepEqual(listBooks(books, 'read').map((b) => b.title), ['A']);
  assert.deepEqual(listBooks(books, 'unread').map((b) => b.title), ['B']);
});
EOF
