import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const cli = fileURLToPath(new URL('../bin/reading-list.js', import.meta.url));
let dir;
let file;

const run = (...args) =>
  spawnSync(process.execPath, [cli, ...args], {
    encoding: 'utf8',
    env: { ...process.env, READING_LIST_FILE: file },
  });

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'reading-list-'));
  file = join(dir, 'books.json');
});
afterEach(() => rmSync(dir, { recursive: true, force: true }));

test('add, read, and list round-trip through the data file', () => {
  let r = run('add', 'Dune', '--author', 'Frank Herbert');
  assert.equal(r.status, 0, r.stderr);
  assert.match(r.stdout, /Added #1: Dune by Frank Herbert/);

  run('add', 'Emma');
  r = run('read', '1');
  assert.equal(r.status, 0, r.stderr);
  assert.match(r.stdout, /Marked #1 as read: Dune/);

  r = run('list');
  assert.equal(r.stdout, '[x] #1 Dune — Frank Herbert\n[ ] #2 Emma\n');

  assert.equal(run('list', '--unread').stdout, '[ ] #2 Emma\n');
  assert.equal(run('list', '--read').stdout, '[x] #1 Dune — Frank Herbert\n');

  const saved = JSON.parse(readFileSync(file, 'utf8'));
  assert.equal(saved.length, 2);
});

test('multi-word titles work without quoting', () => {
  const r = run('add', 'The', 'Left', 'Hand', 'of', 'Darkness');
  assert.match(r.stdout, /Added #1: The Left Hand of Darkness/);
});

test('list on an empty list says so', () => {
  const r = run('list');
  assert.equal(r.status, 0);
  assert.match(r.stdout, /no books/i);
});

test('errors exit non-zero with a message on stderr', () => {
  for (const args of [['read', '9'], ['read', 'abc'], ['add'], ['bogus'], ['list', '--nope']]) {
    const r = run(...args);
    assert.equal(r.status, 1, `expected failure for ${args.join(' ')}`);
    assert.notEqual(r.stderr.trim(), '', `expected stderr for ${args.join(' ')}`);
  }
});

test('a corrupt data file is reported, not overwritten', () => {
  writeFileSync(file, '{not json');
  const r = run('add', 'Dune');
  assert.equal(r.status, 1);
  assert.match(r.stderr, /could not parse/i);
  assert.equal(readFileSync(file, 'utf8'), '{not json');
});

test('no arguments prints usage', () => {
  const r = run();
  assert.equal(r.status, 0);
  assert.match(r.stdout, /usage/i);
});
EOF
