// Pure operations on an array of books. Never mutates its inputs.

export function addBook(books, { title, author = null }) {
  const cleanTitle = String(title ?? '').trim();
  if (!cleanTitle) throw new Error('A title is required.');
  const cleanAuthor = author?.trim() || null;
  const id = books.reduce((max, b) => Math.max(max, b.id), 0) + 1;
  return [...books, { id, title: cleanTitle, author: cleanAuthor, read: false }];
}

export function markRead(books, id) {
  if (!books.some((b) => b.id === id)) throw new Error(`No book with id ${id}.`);
  return books.map((b) => (b.id === id ? { ...b, read: true } : b));
}

export function listBooks(books, status = 'all') {
  if (status === 'read') return books.filter((b) => b.read);
  if (status === 'unread') return books.filter((b) => !b.read);
  return [...books];
}
