import { readFileSync, writeFileSync, renameSync, mkdirSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join } from 'node:path';

export function dataFile() {
  return process.env.READING_LIST_FILE || join(homedir(), '.reading-list.json');
}

export function load(file = dataFile()) {
  let text;
  try {
    text = readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  try {
    const books = JSON.parse(text);
    if (!Array.isArray(books)) throw new Error('expected an array');
    return books;
  } catch (err) {
    throw new Error(`Could not parse ${file}: ${err.message}`);
  }
}

export function save(books, file = dataFile()) {
  mkdirSync(dirname(file), { recursive: true });
  const tmp = `${file}.tmp`;
  writeFileSync(tmp, JSON.stringify(books, null, 2) + '\n');
  renameSync(tmp, file); // atomic replace so a crash can't leave a half-written file
}
EOF
cat > bin/reading-list.js <<'EOF'
#!/usr/bin/env node
import { parseArgs } from 'node:util';
import { addBook, markRead, listBooks } from '../src/reading-list.js';
import { load, save } from '../src/store.js';

const USAGE = `Usage:
  reading-list add <title...> [--author <name>]   Add a book
  reading-list read <id>                          Mark a book as read
  reading-list list [--read | --unread]           List books

Data is stored in $READING_LIST_FILE (default: ~/.reading-list.json).`;

const format = (b) => `[${b.read ? 'x' : ' '}] #${b.id} ${b.title}${b.author ? ` — ${b.author}` : ''}`;

function main(argv) {
  const [command, ...rest] = argv;

  switch (command) {
    case undefined:
    case 'help':
    case '--help':
    case '-h':
      console.log(USAGE);
      return;

    case 'add': {
      const { values, positionals } = parseArgs({
        args: rest,
        options: { author: { type: 'string', short: 'a' } },
        allowPositionals: true,
      });
      const books = addBook(load(), { title: positionals.join(' '), author: values.author });
      save(books);
      const b = books.at(-1);
      console.log(`Added #${b.id}: ${b.title}${b.author ? ` by ${b.author}` : ''}`);
      return;
    }

    case 'read': {
      const { positionals } = parseArgs({ args: rest, allowPositionals: true });
      if (positionals.length !== 1 || !/^\d+$/.test(positionals[0])) {
        throw new Error('Usage: reading-list read <id>');
      }
      const id = Number(positionals[0]);
      const books = markRead(load(), id);
      save(books);
      console.log(`Marked #${id} as read: ${books.find((b) => b.id === id).title}`);
      return;
    }

    case 'list': {
      const { values } = parseArgs({
        args: rest,
        options: { read: { type: 'boolean' }, unread: { type: 'boolean' } },
      });
      if (values.read && values.unread) throw new Error('Use only one of --read or --unread.');
      const status = values.read ? 'read' : values.unread ? 'unread' : 'all';
      const books = listBooks(load(), status);
      console.log(books.length ? books.map(format).join('\n') : 'No books.');
      return;
    }

    default:
      throw new Error(`Unknown command: ${command}\n\n${USAGE}`);
  }
}

try {
  main(process.argv.slice(2));
} catch (err) {
  console.error(`Error: ${err.message}`);
  process.exitCode = 1;
}
EOF
